'use strict';

// MODULES //

var Uint32Array = require( '@stdlib/array/uint32' );
var Uint64 = require( '@stdlib/number/uint64/ctor' );
var assign = require( './assign.js' );


// VARIABLES //

var WORKSPACE = new Uint32Array( 2 );


// MAIN //

/**
* Adds two unsigned 64-bit integer.
*
* @param {Uint64} a - unsigned 64-bit integer
* @param {Uint64} b - unsigned 64-bit integer
* @returns {Uint64} result
*
* @example
* var Uint64 = require( '@stdlib/number/uint64/ctor' );
*
* var a = new Uint64( 5 );
* var b = new Uint64( 10 );
*
* var v = add( a, b );
* // returns <Uint64>[ 15n ]
*/
function add( a, b ) {
	assign( a.hi, a.lo, b.hi, b.lo, WORKSPACE, 1, 0 );
	return Uint64.from( WORKSPACE );
}


// EXPORTS //

module.exports = add;
